(() => {
  'use strict';
  const R=window.CONTINUE_REFERENCE,I=window.CONTINUE_ICONS,G=window.CONTINUE_GUIDES,B=window.CONTINUE_BEHAVIOR_DETAILS;
  const $=s=>document.querySelector(s),main=$('#main');
  if(!R||!I||!G||!B){main.innerHTML='<h1>Não foi possível abrir a documentação.</h1><p>Confira se os arquivos do site estão na mesma pasta e recarregue a página.</p>';return;}
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const slug=s=>normalize(s).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  const rich=s=>esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
  const href=route=>'#'+route;
  const gm=new Map(G.map(x=>[x.id,x])),nm=new Map(R.nodes.map(x=>[x.id,x])),bm=new Map(R.behaviors.map(x=>[x.id,x])),em=new Map(R.expressions.map(x=>[x.id,x]));
  const themeNames={dark:['Escuro','Fundo preto e superfícies neutras.'],light:['Claro','Branco com detalhes suaves.'],rose:['Rosa suave','Um tom rosado e acolhedor.'],gray:['Cinza','Neutro, com contraste equilibrado.'],midnight:['Azul noturno','Azul profundo e detalhes claros.']};
  const behaviorGroupTitles=['Visual e animação','Movimento e toque','Colisão e física','Iluminação','Dados'];
  function icon(key,color='',classes=''){const d=I[key]||I['common/object'];const v=d.viewport||24;return `<svg class="icon ${esc(classes)}" viewBox="0 0 ${v} ${v}" aria-hidden="true" focusable="false" style="color:${esc(color||d.color)}">${d.strokes.map(s=>`<path d="${esc(s.d)}" fill="${s.fill?esc(s.color||'currentColor'):'none'}" stroke="${s.fill?'none':esc(s.color||'currentColor')}" stroke-width="${s.width}" opacity="${s.opacity}" ${s.transform?`transform="${esc(s.transform)}"`:''} stroke-linecap="round" stroke-linejoin="round"/>`).join('')}</svg>`;}
  function iconBadge(key,color='',classes=''){return `<span class="icon-badge ${esc(classes)}" style="--item-color:${esc(color||I[key]?.color||'#A78BFA')}">${icon(key,color)}</span>`;}
  const chevron=()=>icon('common/chevron','', 'chevron');
  function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon');});}
  function guideLink(id){const g=gm.get(id);return g?row(g.title,g.description,g.icon,g.color,'/guia/'+g.id):'';}
  function row(title,description,key,color,route,meta=''){return `<a class="row-link" href="${href(route)}">${iconBadge(key,color,'row-icon')}<span class="row-copy"><span class="row-title">${esc(title)}</span>${description?`<span class="row-hint">${esc(description)}</span>`:''}</span>${meta?`<span class="row-meta">${esc(meta)}</span>`:''}${chevron()}</a>`;}
  function nodeCard(id,showField=false){const n=nm.get(id);if(!n)return '';return `<a class="node-card" href="${href('/no/'+id)}" style="display:block"><div class="node-kind">${icon('common/chevron','', 'caret')}${n.kind==='condition'?'CONDIÇÃO':'AÇÃO'}</div><div class="node-content">${icon(n.icon,n.color)}<div><div class="node-title">${esc(n.title)}</div><div class="node-desc">${n.kind==='condition'?'Executa o próximo nó':'Uma mudança no jogo'}</div></div></div>${showField?`<div class="node-field">${icon('common/object','#A78BFA')}<span><small>OBJETOS</small>Personagem</span>${chevron()}</div>`:''}</a>`;}
  function flow(ids){return `<div class="mini-flow">${ids.filter(id=>nm.has(id)).map((id,i)=>{const n=nm.get(id);return `${i?icon('common/arrow-right'):''}<a class="flow-step" href="${href('/no/'+id)}">${icon(n.icon,n.color)}${esc(n.title)}</a>`;}).join('')}</div>`;}
  function navigation(){const groups=[['COMEÇAR',['primeiro-projeto','editor','fluxos','expressoes','testar']],['ENTENDA O JOGO',['objetos-instancias','cenas','scripts','comportamentos','propriedades-visuais','camadas','camera','variaveis','recursos']]];
    $('#navigation').innerHTML=groups.map(([label,ids])=>`<div class="nav-heading">${label}</div>${ids.map(id=>{const g=gm.get(id);return `<a class="nav-link" href="${href('/guia/'+id)}">${icon(g.icon)}<span>${esc(g.title)}</span></a>`;}).join('')}`).join('')+`<div class="nav-heading">REFERÊNCIA</div>${[['comportamentos','Comportamentos','behavior/property-animation'],['acoes','Ações','script-node/action-create-object'],['condicoes','Condições','script-node/condition-object-clicked'],['expressoes','Expressões','common/calculator']].map(([id,label,key])=>`<a class="nav-link" href="${href('/'+id)}">${icon(key)}<span>${label}</span>${chevron()}</a>`).join('')}<div class="nav-heading">SEU JOGO PRONTO</div><a class="nav-link" href="#/guia/exportar">${icon('export/android')}<span>Exportar para Android</span></a>`;
  }
  function home(){return `<div class="home-hero"><div><div class="eyebrow"><span class="dot"></span>DOCUMENTAÇÃO DA CONTINUE</div><h1>Sua ideia.<br><span class="muted">Seu primeiro jogo.</span></h1><p class="lead">Crie uma cena, adicione objetos e monte as regras com nós. Comece pelo básico e encontre cada recurso quando precisar.</p><div class="hero-actions"><a class="button primary" href="#/guia/primeiro-projeto">Começar agora ${icon('common/arrow-right','#FFFFFF')}</a><a class="text-link" href="#/guia/editor">Conhecer o editor ${icon('common/arrow-right')}</a></div><div class="hero-caption">${icon('common/check','#4ADE80')}Guias curtos. Um assunto de cada vez.</div></div><figure class="flow-showcase" aria-label="Exemplo de fluxo: Cena começou conectado a Criar objeto"><div class="figure-title">${icon('common/flow')}Uma ideia vira uma regra</div>${nodeCard('condition-scene-started')}<div class="node-link-line"></div>${nodeCard('action-create-object',true)}<figcaption class="flow-result">${icon('common/check','#4ADE80')}Ao iniciar a cena, crie o personagem.</figcaption></figure></div>
    <div class="home-grid"><section><div class="section-title"><h2>Comece por aqui</h2><span>Do zero ao primeiro teste</span></div><div class="group-list">${['primeiro-projeto','editor','fluxos','testar'].map(guideLink).join('')}</div></section><section><div class="section-title"><h2>Entenda as peças</h2><span>Cada coisa no seu lugar</span></div><div class="group-list">${['objetos-instancias','scripts','comportamentos','camera'].map(guideLink).join('')}</div></section></div>
    <section><div class="section-title"><h2>Encontre um recurso</h2><a class="text-link" href="#/acoes">Ver referência ${icon('common/arrow-right')}</a></div><div class="reference-grid">${[['comportamentos','Comportamentos','Funções que você combina nos objetos.','behavior/property-animation','#2DD4BF',R.behaviors.length+' comportamentos'],['acoes','Ações e condições','Nós para mudar o jogo e verificar suas regras.','common/flow','#60A5FA',R.nodes.length+' nós'],['expressoes','Expressões','Posições, variáveis, tempo e cálculos nos campos.','common/calculator','#A78BFA','Valores e cálculos']].map(([id,title,description,key,color,count])=>`<a class="reference-tile" href="${href('/'+id)}">${icon(key,color)}<h3>${title}</h3><p>${description}</p><div class="tile-bottom"><span>${count}</span>${chevron()}</div></a>`).join('')}</div></section><aside class="tip-panel">${icon('scene/initial','#FBBF24')}<div><h3>Teste a cena. Depois, compartilhe o jogo.</h3><p>O visualizador abre a cena em edição. Na exportação, o jogo começa pela cena marcada como inicial. <a class="inline-link" href="#/guia/exportar">Veja como exportar para Android.</a></p></div></aside>`;}
  function definitions(items){return `<div class="definition-list">${items.map(([title,description,key='common/object',color=''])=>`<div class="definition-item"><h3>${iconBadge(key,color,'heading-icon')}<span>${esc(title)}</span></h3><p>${rich(description)}</p></div>`).join('')}</div>`;}
  function section(s){return `<section id="${esc(s.id||slug(s.title))}"><h2>${esc(s.title)}</h2>${(s.paragraphs||[]).map(p=>`<p>${rich(p)}</p>`).join('')}${s.steps?`<ol class="step-list">${s.steps.map(([title,p])=>`<li><h3>${esc(title)}</h3><p>${rich(p)}</p></li>`).join('')}</ol>`:''}${s.items?definitions(s.items):''}${s.bullets?`<ul>${s.bullets.map(p=>`<li>${rich(p)}</li>`).join('')}</ul>`:''}${s.example?example(s.example):''}${s.examples?(s.examples.map(example).join('')):''}${s.flow?flow(s.flow):''}${s.note?`<aside class="callout">${icon('common/check')}<p>${rich(s.note)}</p></aside>`:''}</section>`;}
  function example(e){return `<div class="example-box">${e.title?`<h3>${esc(e.title)}</h3>`:''}${e.formula?`<code class="formula">${esc(e.formula)}</code>`:''}${e.text?`<p>${rich(e.text)}</p>`:''}</div>`;}
  function article(page){return `<div class="article-layout" style="--page-accent:${esc(page.color||'#A78BFA')}"><article class="article"><header class="article-header"><div class="article-kicker">${page.tag?`<span class="article-tag">${esc(page.tag)}</span>`:''}<span>${esc(page.kicker||page.group||'Guia de uso')}</span></div><div class="article-title">${iconBadge(page.icon,page.color,'title-icon')}<h1>${esc(page.title)}</h1></div><button class="icon-button copy-link" data-copy-link aria-label="Copiar link desta página" title="Copiar link">${icon('common/link')}</button><p class="lead">${rich(page.description)}</p></header>${page.platform?`<div class="platform-note">${esc(page.platform)}</div>`:''}${page.sections.map(section).join('')}${page.related?.length?`<section class="related"><h2>Continue por aqui</h2><div class="group-list">${page.related.map(guideLink).join('')}</div></section>`:''}</article></div>`;}
  function behaviorPage(b){const d=B[b.id];return article({...b,tag:'Comportamento',kicker:behaviorGroupTitles[b.category],description:b.id==='light-blocker'?'Bloqueia luz e projeta sombras com o contorno escolhido.':b.description,sections:[{title:'Para que serve',paragraphs:[d.intro]},{title:'Campos',items:d.fields},{title:'Exemplo',example:{text:d.example}},{title:'Regras',bullets:d.rules}],related:d.related});}
  const objectNode=n=>['objects','movement','appearance','animation','collision','raycast','particles','behaviors','text'].includes(n.category)||(n.category==='touch'&&!n.id.startsWith('condition-screen-'))||['action-center-camera-on-object','condition-object-in-camera','condition-object-entered-camera','condition-object-exited-camera'].includes(n.id);
  function nodePage(n){const category=R.categories.find(c=>c.id===n.category),condition=n.kind==='condition';let fields=[];
    if(objectNode(n))fields=[['Objetos','Escolha o modelo de objeto que participa da regra. Nos campos com seleção múltipla, você pode escolher vários.','common/object','#A78BFA'],[condition?'Verificação':'Instâncias',condition?'Escolha quais instâncias devem atender à regra. Qualquer instância e Todas as instâncias têm resultados diferentes.':'Escolha quais instâncias recebem a mudança. Os filtros permitem usar números e expressões.','instance/all','#38BDF8']];
    if(n.id==='action-create-object')fields=[['Objetos','Escolha um ou mais modelos para criar novas cópias.','common/object','#A78BFA'],['Quantidade','Informe quantas instâncias serão criadas por execução.','common/quantity','#60A5FA'],['Posição X e Y','Defina onde as novas instâncias aparecem. Os campos também aceitam expressões.','property/x','#60A5FA'],['Camada','Escolha em qual camada as instâncias serão criadas.','layer/stack','#FB923C']];
    if(n.id==='condition-object-flipped')fields.push(['Verificar e direção','Escolha Objeto, Sprite, Forma ou Texto e depois Horizontal ou Vertical.','flip-axis/horizontal','#34D399']);
    if(n.category==='layers')fields.push(['Camada','Escolha a camada que será alterada ou verificada. Os valores do card definem a regra.','layer/stack','#FB923C']);
    if(n.category==='sounds')fields.push(['Som e canal','Escolha o som do projeto e, quando disponível, o canal. O número do canal pode usar expressão.','common/sound','#22D3EE']);
    if(n.category==='keyboard')fields.push(['Tecla','Abra o seletor para escolher a tecla ou combinação. Confira os campos de tempo quando a condição os pedir.','script-node/condition-key-pressed','#60A5FA']);
    if(n.category==='variables')fields.push(['Variável','Escolha a origem e configure a variável ou a coleção de acordo com os campos do nó.','expression/scene-variable','#60A5FA']);
    const custom=window.CONTINUE_NODE_EXAMPLES[n.id];const linked=custom?.[2]&&nm.has(custom[2])?custom[2]:(condition?'action-show-object':'condition-object-clicked');
    const exampleTitle=custom?.[0]||(condition?'Use a condição para decidir uma ação.':'Ligue a ação a uma interação.');
    const exampleText=custom?.[1]||(condition?'Conecte Mostrar objeto abaixo para exibir um aviso quando esta regra for atendida. Configure o alvo do aviso no card da ação.':'Conecte a ação depois de Objeto clicado. Escolha um botão na condição e ajuste os campos desta ação para definir sua resposta.');
    const rules=[];if(condition){rules.push(n.description);if(n.id==='condition-object-visible')rules.push('Consulta o estado de visibilidade do objeto. Não verifica se ele aparece dentro da câmera.');if(objectNode(n))rules.push('A seleção de instâncias faz parte da verificação. Basta uma ou todas precisam atender, conforme a opção escolhida.');}
    else {rules.push('A posição do nó no fluxo importa: os nós de cima são processados primeiro.');if(!['flow','scene'].includes(n.category))rules.push('Quando o card oferecer repetição, escolha a configuração de execução adequada. Uma mudança contínua pode acontecer a cada atualização.');}
    if(n.category==='window')rules.push('Estas opções são específicas da janela no Windows. Não controlam a orientação de um celular.');
    if(n.category==='raycast')rules.push('Escolha um raio existente no objeto. O nome identifica qual raio será consultado.');
    if(n.category==='particles')rules.push('Um objeto pode ter vários efeitos. Confira o nome do efeito escolhido.');
    const sections=[{title:'Para que serve',paragraphs:[condition?'Verifica esta regra antes de continuar os nós conectados abaixo.':'Faz a mudança descrita no objeto, recurso ou parte do jogo escolhida. Configure o resultado nos campos do card.']},...(fields.length?[{title:'Campos',items:fields}]:[]),
      {title:'Exemplo',example:{title:exampleTitle,text:exampleText},flow:condition?[n.id,linked]:[linked,n.id]},
      {title:'Regras',bullets:rules}];
    return article({...n,tag:condition?'Condição':'Ação',kicker:category.title,platform:n.category==='window'?'Recurso específico de Windows. A exportação para Windows ainda não está disponível nesta versão.':'',sections,related:['fluxos',objectNode(n)?'instancias':'scripts','expressoes']});
  }
  function expressionSamples(e){if(window.CONTINUE_MATH_EXAMPLES[e.id])return window.CONTINUE_MATH_EXAMPLES[e.id];
    const token=e.token||(e.objectVariable?'personagem.variable.vida':e.id==='scene-variable'?'scene.variable.pontos':e.id==='global-variable'?'global.variable.moedas':'personagem.'+e.property);
    if(e.id==='text-content')return [[token,'Lê o conteúdo do objeto com Texto. Use em um campo que aceite texto.'],['"Mensagem: " + '+token,'Combina uma mensagem fixa com o conteúdo lido.']];
    if(e.category==='rays')return [[token,'Consulte o raio chamado Chão no objeto Personagem. Os nomes são exemplos; use a lupa para inserir os do projeto.'],[e.id==='ray-hit'?token+' * 100':token+' + 8',e.id==='ray-hit'?'Converte 0 ou 1 em um valor de 0 ou 100.':'Acrescenta um deslocamento ou margem ao valor detectado.']];
    if(e.id==='time-delta')return [[token,'Obtém o intervalo da atualização em segundos.'],['240 * time.delta','Calcula um deslocamento por atualização a partir de uma velocidade de 240 por segundo. Não multiplique novamente se a ação já usa velocidade.']];
    if(e.id==='touch-is-down')return [[token,'Retorna 1 durante o toque e 0 quando não há toque.'],[token+' * 100','Transforma esse estado em 0 ou 100 para um cálculo.']];
    if(e.id.includes('opacity')||e.id.includes('transparency')||e.id.includes('progress'))return [[token,'Lê o valor atual. Use a referência inserida para o objeto do seu projeto.'],['math.clamp('+token+' + 10, 0, 100)','Soma 10 sem deixar o resultado sair de 0 a 100.']];
    if(e.category==='variables')return [[token,'Lê a variável ou a contagem escolhida pela lupa. Os nomes de variável são exemplos.'],[token+' + 1','Usa o valor atual em um cálculo.']];
    return [[token,e.dynamic?'O nome do som ou o número do canal é um exemplo. Insira a referência pela lupa.':'Use este valor em um campo que aceite expressão. Quando houver um objeto, escolha-o pela lupa.'],[token+' + 10','Combina a referência com um valor fixo. Confira a unidade do campo em que está usando o resultado.']];
  }
  function expressionPage(e){const examples=expressionSamples(e).map(([formula,text],i)=>({title:i?'Outro exemplo':'Primeiro exemplo',formula,text}));const objectReference=!!(e.property||e.objectVariable);return article({...e,kicker:'Expressões · '+R.expressionCategories.find(c=>c.id===e.category).title,color:I[e.icon]?.color||'#A78BFA',sections:[{title:'Como inserir',steps:[['Abra a lupa','Toque na lupa do campo que aceita expressões.'],['Escolha o valor',e.dynamic?'Escolha o objeto e o raio, ou o som/canal correspondente ao seu projeto.':'Encontre a categoria e escolha este valor. Se o seletor pedir, escolha o objeto, a variável e a instância.'],['Complete a expressão','Use o valor diretamente ou combine com operações e outros valores.']]},{title:'Exemplos',examples},{title:'Antes de usar',bullets:[e.description,e.dynamic?'Esta referência depende de um recurso do projeto. Os nomes dos exemplos não são criados automaticamente.':objectReference?'A referência usa o objeto e a instância escolhidos. Não confunda propriedades locais com a posição do objeto.':'Confira a unidade do valor e do campo em que ele será usado.','O resultado precisa ser do tipo que o campo aceita: número, texto ou lógico.']}],related:['expressoes',e.category==='variables'?'variaveis':e.category==='camera'?'camera':objectReference?'instancias':'fluxos']});}
  const catalogInfo={comportamentos:['Comportamentos','Adicione funções e combine o que o objeto precisa.','behavior/property-animation','#2DD4BF'],acoes:['Ações','Escolha o que deve mudar no jogo.','script-node/action-create-object','#4ADE80'],condicoes:['Condições','Defina quando o próximo nó pode continuar.','script-node/condition-object-clicked','#38BDF8'],expressoes:['Expressões','Use valores do jogo e cálculos nos campos.','common/calculator','#A78BFA']};
  let activeCatalog='',catalogQuery='';
  function catalogItems(type){return type==='comportamentos'?R.behaviors:type==='expressoes'?R.expressions:R.nodes.filter(n=>n.kind===(type==='condicoes'?'condition':'action'));}
  function catalogRoute(type,item){return type==='comportamentos'?'/comportamento/'+item.id:type==='expressoes'?'/expressao/'+item.id:'/no/'+item.id;}
  function catalogGroups(type){if(type==='comportamentos')return behaviorGroupTitles.map((title,id)=>({id,title,description:'',icon:R.behaviors.find(b=>b.category===id)?.icon,color:R.behaviors.find(b=>b.category===id)?.color}));
    if(type==='expressoes')return R.expressionCategories;
    return [...R.categories].sort((a,b)=>type==='acoes'?a.actionOrder-b.actionOrder:a.conditionOrder-b.conditionOrder);}
  let visibleCatalog=new Map();
  function catalogBody(type,query=''){visibleCatalog=new Map();const q=normalize(query.trim()),tokens=q.split(/\s+/).filter(Boolean);const items=catalogItems(type).filter(n=>tokens.every(t=>normalize(n.title+' '+n.description+' '+(n.search||'')).includes(t)));if(!items.length)return `<div class="empty-results">${icon('common/search')}Nenhum resultado para esta busca.<p>Tente outro nome ou uma palavra mais curta.</p></div>`;
    return catalogGroups(type).map(c=>{const children=items.filter(n=>n.category===c.id);if(!children.length)return '';visibleCatalog.set(String(c.id),children);return `<details class="catalog-group" data-category="${esc(c.id)}" ${q?'open':''}><summary>${icon(c.icon,c.color)}<span class="row-copy"><span class="group-title">${esc(c.title)}</span>${c.description?`<span class="group-description">${esc(c.description)}</span>`:''}</span><span class="group-count">${children.length}</span>${chevron()}</summary><div class="catalog-children">${q?catalogRows(type,children):''}</div></details>`;}).join('');}
  function catalogRows(type,items){return items.map(n=>row(n.title,n.description,n.icon,n.color,catalogRoute(type,n))).join('');}
  function catalog(type){activeCatalog=type;catalogQuery='';const [title,description,key,color]=catalogInfo[type];return `<header class="catalog-header"><div class="eyebrow">REFERÊNCIA</div><div class="article-title">${icon(key,color)}<h1>${title}</h1></div><p style="margin-top:17px">${description} Abra uma categoria para ver os itens.</p></header><label class="local-search">${icon('common/search')}<input type="search" id="catalog-search" placeholder="Buscar ${title.toLowerCase()}…" aria-label="Buscar ${title.toLowerCase()}" autocomplete="off"></label><div class="catalog-note">${icon('common/flow')}Nomes e ícones do aplicativo atual.</div><div id="catalog-body">${catalogBody(type)}</div>${type==='expressoes'?'<aside class="tip-panel">'+icon('common/search')+'<div><h3>Os valores acompanham o projeto.</h3><p>Referências de raios, sons e variáveis aparecem conforme os recursos criados. Os exemplos usam nomes ilustrativos.</p></div></aside>':''}`;}
  const positions=new Map();let currentRoute='',searchKind='all',restoreFocus=null,toastTimer;
  function routePath(){let route=location.hash.slice(1)||'/';try{route=decodeURIComponent(route);}catch{return '/';}return route.replace(/\/$/,'')||'/';}
  function routeMeta(route){const parts=route.split('/').filter(Boolean);if(!parts.length)return ['Início'];if(parts[0]==='guia')return ['Guias',gm.get(parts[1])?.title||'Página'];if(catalogInfo[parts[0]])return ['Referência',catalogInfo[parts[0]][0]];if(parts[0]==='comportamento')return ['Comportamentos',bm.get(parts[1])?.title||'Página'];if(parts[0]==='expressao')return ['Expressões',em.get(parts[1])?.title||'Página'];if(parts[0]==='no'){const n=nm.get(parts[1]);return [n?.kind==='condition'?'Condições':'Ações',n?.title||'Nó'];}return ['Documentação'];}
  function render(){const route=routePath();if(currentRoute)positions.set(currentRoute,scrollY);currentRoute=route;activeCatalog='';const [kind,id]=route.split('/').filter(Boolean);let title='Documentação';
    if(route==='/')main.innerHTML=home();else if(kind==='guia'&&gm.has(id)){const g=gm.get(id);main.innerHTML=article(g);title=g.title;}else if(catalogInfo[kind]&&!id){main.innerHTML=catalog(kind);title=catalogInfo[kind][0];}else if(kind==='comportamento'&&bm.has(id)){main.innerHTML=behaviorPage(bm.get(id));title=bm.get(id).title;}else if(kind==='no'&&nm.has(id)){main.innerHTML=nodePage(nm.get(id));title=nm.get(id).title;}else if(kind==='expressao'&&em.has(id)){main.innerHTML=expressionPage(em.get(id));title=em.get(id).title;}else main.innerHTML=article({title:'Página não encontrada',description:'Esse endereço não corresponde a uma página desta documentação.',icon:'common/search',sections:[{title:'Encontre o assunto',paragraphs:['Use a busca ou o menu para escolher um guia.']}],related:['primeiro-projeto']});
    document.title=title+' · Continue';const crumbs=routeMeta(route);$('#breadcrumb').innerHTML=`<a href="#/">Documentação</a>${crumbs.map(t=>chevron()+`<span>${esc(t)}</span>`).join('')}`;
    $('#navigation').querySelectorAll('a').forEach(a=>{if(a.hash==='#'+route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    closeNavigation();main.style.animation='none';void main.offsetHeight;main.style.animation='';document.documentElement.style.scrollBehavior='auto';window.scrollTo(0,positions.get(route)||0);requestAnimationFrame(()=>document.documentElement.style.scrollBehavior='');main.focus({preventScroll:true});
  }
  function closeNavigation(){document.body.classList.remove('nav-open');$('.site-shell').inert=false;$('#nav-scrim').hidden=true;$('#menu-button').setAttribute('aria-expanded','false');$('#sidebar').removeAttribute('aria-modal');$('#sidebar').removeAttribute('role');if(matchMedia('(max-width:700px)').matches)$('#sidebar').inert=true;}
  function openNavigation(){document.body.classList.add('nav-open');$('.site-shell').inert=true;$('#nav-scrim').hidden=false;$('#menu-button').setAttribute('aria-expanded','true');$('#sidebar').inert=false;$('#sidebar').setAttribute('role','dialog');$('#sidebar').setAttribute('aria-modal','true');$('#sidebar a').focus();}
  function notify(text){const t=$('#toast');t.textContent=text;t.classList.add('shown');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('shown'),2200);}
  function openDialog(id){const active=document.activeElement;closeNavigation();restoreFocus=active?.closest('#sidebar')&&matchMedia('(max-width:700px)').matches?$('#menu-button'):active;const d=$('#'+id);d.showModal();if(id==='search-dialog'){$('#search-input').value='';searchKind='all';updateSearch();$('#search-input').focus();}else renderThemeOptions();}
  function closeDialog(id){const d=$('#'+id);if(d.open)d.close();}
  function theme(){return document.documentElement.dataset.theme;}
  function renderThemeOptions(){const options=$('#theme-options');options.setAttribute('role','radiogroup');options.setAttribute('aria-label','Tema da documentação');options.innerHTML=Object.entries(themeNames).map(([id,[title,hint]])=>`<button class="theme-option" role="radio" aria-checked="${theme()===id}" data-set-theme="${id}">${icon('theme/'+id,'var(--sub)')}<span><strong>${title}</strong><small>${hint}</small></span><span class="theme-radio" aria-hidden="true"></span></button>`).join('');}
  const searchPages=[...G.map(g=>({route:'/guia/'+g.id,title:g.title,description:g.description,icon:g.icon,color:g.color,kind:'guide',kindLabel:'Guia'})),...R.behaviors.map(b=>({...b,route:'/comportamento/'+b.id,kind:'behavior',kindLabel:'Comportamento'})),...R.nodes.map(n=>({...n,route:'/no/'+n.id,kindLabel:n.kind==='condition'?'Condição':'Ação'})),...R.expressions.map(e=>({...e,route:'/expressao/'+e.id,kind:'expression',kindLabel:'Expressão'}))];
  function updateSearch(){const q=normalize($('#search-input').value.trim()),tokens=q.split(/\s+/).filter(Boolean);$('#search-filters').innerHTML=[['all','Tudo'],['guide','Guias'],['behavior','Comportamentos'],['action','Ações'],['condition','Condições'],['expression','Expressões']].map(([id,title])=>`<button data-search-kind="${id}" aria-pressed="${searchKind===id}">${title}</button>`).join('');
    let results=searchPages.filter(p=>(searchKind==='all'||p.kind===searchKind)&&tokens.every(t=>normalize(p.title+' '+p.description+' '+(p.search||'')).includes(t)));
    if(q)results.sort((a,b)=>(normalize(a.title)===q?-20:normalize(a.title).startsWith(q)?-10:normalize(a.title).includes(q)?-5:0)-(normalize(b.title)===q?-20:normalize(b.title).startsWith(q)?-10:normalize(b.title).includes(q)?-5:0));
    else results=results.filter(p=>p.kind==='guide');
    $('#search-results').innerHTML=results.length?results.slice(0,14).map(p=>`<a class="search-result" href="${href(p.route)}">${icon(p.icon,p.color)}<span><strong>${esc(p.title)}</strong><small>${esc(p.kindLabel)} · ${esc(p.description)}</small></span>${chevron()}</a>`).join(''):`<div class="empty-results">${icon('common/search')}Nenhum resultado.<p>Tente uma palavra como câmera, colisão ou variável.</p></div>`;
  }
  let searchTimer;
  document.addEventListener('click',async e=>{const target=e.target.closest('button,a');if(!target)return;
    if(target.classList.contains('skip')){e.preventDefault();main.focus({preventScroll:true});main.scrollIntoView({behavior:'auto'});return;}
    if(target.hasAttribute('data-search')){openDialog('search-dialog');return;}
    if(target.hasAttribute('data-theme-button')){openDialog('theme-dialog');return;}
    if(target.dataset.closeDialog){closeDialog(target.dataset.closeDialog);return;}
    if(target.dataset.setTheme){const value=target.dataset.setTheme;if(!themeNames[value])return;document.documentElement.dataset.theme=value;document.querySelector('meta[name=theme-color]').content=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();try{localStorage.setItem('continue-docs-theme',value);}catch{}renderThemeOptions();$('#theme-options [data-set-theme="'+value+'"]').focus();return;}
    if(target.dataset.searchKind){searchKind=target.dataset.searchKind;updateSearch();$('#search-filters [data-search-kind="'+searchKind+'"]').focus();return;}
    if(target.hasAttribute('data-copy-link')){try{await navigator.clipboard.writeText(location.href);notify('Link copiado.');}catch{notify('Não foi possível copiar o link.');}return;}
    if(target.tagName==='A'&&target.hash.startsWith('#/')){if($('#search-dialog').open)closeDialog('search-dialog');if(target.hash==='#'+currentRoute){closeNavigation();document.documentElement.style.scrollBehavior='auto';window.scrollTo(0,0);document.documentElement.style.scrollBehavior='';}}
  });
  document.addEventListener('input',e=>{if(e.target.id==='search-input'){clearTimeout(searchTimer);searchTimer=setTimeout(updateSearch,70);}if(e.target.id==='catalog-search'){catalogQuery=e.target.value;$('#catalog-body').innerHTML=catalogBody(activeCatalog,catalogQuery);}});
  document.addEventListener('toggle',e=>{if(!e.target.matches?.('details.catalog-group')||!e.target.open)return;const container=e.target.querySelector('.catalog-children');if(!container.children.length)container.innerHTML=catalogRows(activeCatalog,visibleCatalog.get(e.target.dataset.category)||[]);},true);
  document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#search-dialog').open)closeDialog('search-dialog');else openDialog('search-dialog');}
    if(e.key==='Escape'&&document.body.classList.contains('nav-open')){closeNavigation();$('#menu-button').focus();}
    if($('#theme-dialog').open&&['ArrowDown','ArrowUp','ArrowLeft','ArrowRight'].includes(e.key)){const options=[...$('#theme-options').querySelectorAll('button')];const i=options.indexOf(document.activeElement);if(i>=0){e.preventDefault();const forward=e.key==='ArrowDown'||e.key==='ArrowRight';options[(i+(forward?1:options.length-1))%options.length].click();}}
    if($('#search-dialog').open&&['ArrowDown','ArrowUp'].includes(e.key)){const rows=[...$('#search-results').querySelectorAll('a')];if(rows.length){e.preventDefault();const i=rows.indexOf(document.activeElement),next=e.key==='ArrowDown'?Math.min(rows.length-1,i+1):i-1;if(next<0)$('#search-input').focus();else rows[next].focus();}}
    if(e.key==='Tab'&&document.body.classList.contains('nav-open')){const focusable=[...$('#sidebar').querySelectorAll('a,button,summary')].filter(el=>el.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
  });
  for(const d of document.querySelectorAll('dialog')){d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});d.addEventListener('close',()=>{restoreFocus?.focus?.({preventScroll:true});});}
  $('#menu-button').addEventListener('click',()=>document.body.classList.contains('nav-open')?closeNavigation():openNavigation());$('#nav-scrim').addEventListener('click',closeNavigation);
  matchMedia('(max-width:700px)').addEventListener('change',e=>{closeNavigation();$('#sidebar').inert=e.matches;});
  window.addEventListener('hashchange',render);navigation();hydrate();render();
})();
